package com.jacekgajek.kapelusz.model

import com.jacekgajek.kapelusz.ops.Rejection
import kotlinx.serialization.Serializable

/** Entity ids are UUIDv7 strings generated by clients. */
typealias Id = String

/** Party id of the band fund in transfers and settlement lines. */
const val BAND_FUND: Id = "band-fund"

/**
 * Holder of collected money that has not come in yet: a fee the organiser still owes (ITERATION_4 §2.2). It counts in
 * the event's income and shares but is never asked to pay; "Received…" moves it to whoever got it.
 */
const val ORGANISER: Id = "organiser"

/** Roles form a single cumulative axis: each role can do everything the previous one can. */
@Serializable
enum class Role {
    /**
     * Sees only their own events, costs and what they receive; adds their own costs; never holds money (ITERATION_4
     * §1.1). Below [MEMBER], which can do everything an artist can, but not "at least [VIEWER]" in what it sees: viewers
     * see everything.
     */
    VIEWER, ARTIST, MEMBER,

    /**
     * The band's leader ("Leader" in the app): runs the events and the money, and manages the members, roles and
     * invites. Also had an Leader role above it until 2026-10-25 (ITERATION_5 §11): merged, as a band's leader is its leader.
     */
    LEAD,
    OWNER;

    fun atLeast(other: Role) = ordinal >= other.ordinal
}

/**
 * Entry on the band roster. Linked to at most one app user ([userId] = Google `sub`).
 * [role] only matters while the member is linked. Roster order is the list order in [Band.members].
 */
@Serializable
data class Member(
    val id: Id,
    val name: String,
    val userId: String? = null,
    val role: Role = Role.MEMBER,
    val archived: Boolean = false,
    /**
     * The linked user's Google photo (ITERATION_2 §7.4), set by the server at sign-in and when joining; not an
     * operation, not in the history, and ignored by undo.
     */
    val pictureUrl: String? = null,
    /** Where their share starts in a new event (ITERATION_4 §2.3): a percentage weight, or [shareFixed] when set. */
    val shareWeight: Int = DEFAULT_WEIGHT,
    val shareFixed: Money? = null,
    /**
     * Who they settle together with (ITERATION_5 §7): in events where both take part, the two are one party on
     * Settlement and in its transfers, and separate everywhere else. Both members name each other.
     */
    val settlesWith: Id? = null,
    /** Who they invited to settle together, while that member has not answered (ITERATION_5 §7). */
    val invitedToSettle: Id? = null,
    /**
     * The phone number bandmates send them money to with BLIK (ITERATION_5 §8), as stored by [BlikPhone.normalize]; set
     * only by the member, kept out of the history and of undo, and gone with the linked account.
     */
    val blikPhone: String? = null,
) {
    /** A participant with this member's default share. */
    fun asParticipant(addedBy: Id? = null) = Participant(id, shareWeight, addedBy, shareFixed)
}

/** Full state of one band; stored as `bands/{id}/state.json`. */
@Serializable
data class Band(
    val id: Id,
    val name: String,
    val currency: String,
    val members: List<Member> = emptyList(),
    /** Member who physically holds the band fund. The band fund is disabled while null. */
    val treasurerMemberId: Id? = null,
    val events: List<Event> = emptyList(),
    val costs: List<Cost> = emptyList(),
    val fundEntries: List<FundEntry> = emptyList(),
    /** Agenda times new events get (ITERATION_2 §4.1); null = the defaults, Arrival, Sound check and Concert start. */
    val agendaTemplate: List<AgendaTemplateItem>? = null,
    /** Highest applied operation sequence number per client install, for idempotent sync. */
    val lastSeq: Map<String, Long> = emptyMap(),
    /**
     * The latest refusals per client install, so a retried push (whose first answer was lost) reports them again
     * instead of treating them as plain duplicates. Bounded by [com.jacekgajek.kapelusz.ops.Engine.REMEMBERED_REJECTIONS].
     */
    val recentRejections: Map<String, List<RecordedRejection>> = emptyMap(),
) {
    fun member(id: Id): Member? = members.firstOrNull { it.id == id }
    fun memberOfUser(userId: String): Member? = members.firstOrNull { it.userId == userId }

    /**
     * The member (archived ones too) already called [name], ignoring letter case and surrounding spaces, other than
     * [except]: member names are unique (ITERATION_5 §12).
     */
    fun memberNamed(name: String, except: Id? = null): Member? =
        members.firstOrNull { it.id != except && it.name.trim().equals(name.trim(), ignoreCase = true) }
    fun event(id: Id): Event? = events.firstOrNull { it.id == id }
    fun cost(id: Id): Cost? = costs.firstOrNull { it.id == id }
    val owner: Member? get() = members.firstOrNull { it.role == Role.OWNER }

    companion object {
        /** A new band whose creator becomes the owner, linked to a fresh roster member. */
        fun create(id: Id, name: String, currency: String, ownerMemberId: Id, ownerName: String, ownerUserId: String) =
            Band(
                id = id,
                name = name,
                currency = currency,
                members = listOf(Member(ownerMemberId, ownerName, ownerUserId, Role.OWNER)),
            )
    }
}

/** A refusal remembered in [Band.recentRejections]. */
@Serializable
data class RecordedRejection(val opId: Id, val rejection: Rejection)

/** The agenda times new events get: Arrival, Sound check and Concert start unless the leaders changed it. */
val Band.effectiveAgendaTemplate: List<AgendaTemplateItem>
    get() = agendaTemplate ?: AgendaKind.entries.map { AgendaTemplateItem(it) }

/** [band] with the photo of [userId]'s member set to [url] (unchanged if they are not a member). */
fun Band.withPicture(userId: String, url: String?): Band =
    copy(members = members.map { if (it.userId == userId && it.userId != null) it.copy(pictureUrl = url) else it })
